import subprocess,re,glob
ops=['g2-clear.red','paper.red','snake.red','stone.red','vampire.red']
rows=[]
for f in glob.glob('/tmp/rand/*.red'):
    wins=[]
    for o in ops:
        z=subprocess.run(['pmars','-b','-r','100','-c','80000','-f',f,'warriors/'+o],capture_output=True,text=True).stdout
        q=next((x for x in z.splitlines() if x.startswith('Results:')),None)
        if q: wins.append(int(q.split()[1]))
    if len(wins)==5: rows.append((min(wins),sum(wins),f,wins))
for r in sorted(rows,reverse=True)[:20]: print(r)
